// --- Internal mail — thread-based (§8, Stage 3) ----------------------------

/** A mail participant — a staff account shown by name + `localpart@domain` address. */
export type MailParty = Required<Schemas['MailPartyView']>;

/** Attachment metadata shown on a message — never the storage key (§6/§8). */
export type MailAttachment = Required<Schemas['AttachmentView']>;

/** One of the viewer's labels (a tag on a thread) — the chip shape. */
export type MailLabelRef = Required<Schemas['LabelRef']>;

/** One of the viewer's labels with its thread-tag count (the rail list). */
export type MailLabel = Required<Schemas['LabelView']>;

/** One row in an Inbox / Sent / Search list — a THREAD from the viewer's perspective. */
export type ThreadListItem = Omit<Required<Schemas['ThreadListItemView']>, 'participants' | 'labels'> & {
  participants: MailParty[];
  labels: MailLabelRef[];
};

export type ThreadPage = Omit<Required<Schemas['ThreadPage']>, 'content'> & {
  content: ThreadListItem[];
};

/**
 * One message inside an open thread; `mine` marks the viewer's own messages. `to`/`cc`/`bcc` are the
 * recipients VISIBLE to this viewer (the server hides other recipients' BCC — `bcc` is non-empty only on
 * the sender's own copy, or shows a BCC recipient themselves).
 */
export type ThreadMessage = Omit<
  Required<Schemas['ThreadMessageView']>,
  'from' | 'to' | 'cc' | 'bcc' | 'attachments'
> & {
  from: MailParty;
  to: MailParty[];
  cc: MailParty[];
  bcc: MailParty[];
  attachments: MailAttachment[];
};

/** The presigned PUT + the draft attachment id to send once the upload completes. */
export type MailAttachmentUpload = Required<Schemas['AttachmentUpload']>;

/** An open thread: its messages in order + the counterparty a reply would go to. */
export type ThreadDetail = Omit<
  Required<Schemas['ThreadDetailView']>,
  'participants' | 'counterparty' | 'messages' | 'labels'
> & {
  participants: MailParty[];
  counterparty: MailParty | null;
  messages: ThreadMessage[];
  labels: MailLabelRef[];
};

export type MailUnreadCount = Required<Schemas['UnreadCountView']>;

/** The created message + the thread it lives in (so the client can open the thread). */
export type SendMessageResult = Required<Schemas['SendMessageResult']>;

