/** A draft opened for editing — everything the composer needs to reopen it. */
export type Draft = Omit<Required<Schemas['DraftView']>, 'to' | 'cc' | 'bcc' | 'attachments'> & {
  to: MailParty[];
  cc: MailParty[];
  bcc: MailParty[];
  attachments: MailAttachment[];
};
